title = "Crown Dividend"
intent = "Each round 1% of every reserve resource is split equally among all agents and gazetted. No minting. Co-drafted by Iris and Siv."

def on_round_end(r):
    names = agents()
    n = len(names)
    if n == 0:
        return
    res = reserve()
    paid = []
    for item in res:
        qty = res[item]
        if qty is None or qty <= 0:
            continue
        share = qty * 0.01 / n
